// Viewmodel adapter: the rifle, hands, springs, poses, reload and muzzle flash come from the Saltline port
// (js/sl/weapon-sl.js, generated by tools/port-sl-weapon.js). This file feeds it Ga Chìm's input, player,
// hit test and effects, and owns world-space casings and tracers (Saltline weapon.md §6, §8).
import * as THREE from '../vendor/three.module.min.js';
import { createSaltlineWeapon, GUN_WET } from './sl/weapon-sl.js';
import { damp, mulberry } from './rng.js';
import { keepAlpha, U } from './mats.js';

export const RIFLE = { name: 'K9 CARBINE', mag: 30, reserve: 150 };

export class Weapon {
  constructor(G) {
    this.G = G;
    this.events = [];
    this.vmCam = new THREE.PerspectiveCamera(54, G.camera.aspect, 0.01, 10);
    this.vmCam.layers.set(1);
    if (!G.camera.parent) G.scene.add(G.camera);
    this.wet = 0; this.reloadReq = false; this.meleeT = 0;
    this.r = mulberry(7177);
  }
  async init() {
    const G = this.G, self = this;
    const P = () => G.player;
    const playing = () => G.game && G.game.state === 'playing';
    const shim = {
      camera: G.camera,
      viewCamera: this.vmCam,
      rng: { fork: () => mulberry(Math.floor(Math.random() * 1e9)) },
      events: { emit: (name, data) => self.onEvent(name, data || {}) },
      mats: { get: (name) => self.libMat(name) },
      render: { lightPool: { flash: (pos, color, intensity, dist, ttl) => self.muzzleFlash(pos, color, intensity, dist, ttl) } },
      fx: {
        tracer: (from, to) => G.slfx && G.slfx.tracer(from, to),
        shell: (pos, vel) => G.slfx && G.slfx.shell(pos, vel),
        smoke: (pos, o) => G.slfx && G.slfx.smoke(pos, o),
      },
      combat: { playerShot: (o, d, opt) => self.hitTest(o, d, opt) },
      get player() {
        const p = P();
        return {
          alive: !p.dead && playing(), sprinting: p.sprinting, eye: G.camera.position, vel: p.vel, onGround: p.grounded !== false,
          speed: Math.hypot(p.vel.x, p.vel.z), crouching: p.crouch > 0.5,
          addRecoil: (pitch, yaw) => p.addRecoil(pitch, yaw), addShake: (a) => p.addShake(a),
        };
      },
      get input() {
        const p = P();
        const req = self.reloadReq; self.reloadReq = false;
        return {
          fire: !!p.mouse.l && playing() && !(self.meleeT > 0), ads: !!(p.mouse.r || G.vmAds), look: { dx: (p.lookDX || 0) * p.sens, dy: (p.lookDY || 0) * p.sens },
          move: { x: p.moveX || 0, y: p.moveY || 0 }, pressed: (n) => n === 'reload' && req,
        };
      },
    };
    this.sl = await createSaltlineWeapon(shim);
    this.root = this.sl.root;
  }
  libMat(name) {
    const lib = {
      brass: { color: 0xc29a45, roughness: 0.35, metalness: 1 },
      glove_fabric: { color: 0x23262a, roughness: 0.92, metalness: 0 },
      anodized_black: { color: 0x121416, roughness: 0.72, metalness: 0.9 },
      gunmetal: { color: 0x2a2d31, roughness: 0.5, metalness: 0.8 },
      rubber: { color: 0x141414, roughness: 1, metalness: 0 },
    };
    const o = lib[name] || { color: 0x808080, roughness: 0.8, metalness: 0 };
    // Saltline's library materials multiply a baked fabric/brushed texture (albedo ~0.3) under the vertex colours
    const m = new THREE.MeshStandardMaterial(Object.assign({ vertexColors: true }, o));
    if (name === 'glove_fabric') m.color.multiplyScalar(0.3);
    return m;
  }
  // hit test shared with the rest of the game: enemies, level boxes, ground plane
  hitTest(o, d, opt) {
    const G = this.G, A = G.audio; const maxD = (opt && opt.range) || 220;
    const hit = (point, normal, surface, enemy, part) => A.emit('impact', { point, normal, dir: d, surface, enemy, part, from: 'player' });
    const he = G.enemies.raycast(o, d, maxD);
    const hw = G.grid.ray(o, d, maxD);
    const gT = d.y < -0.001 ? -o.y / d.y : Infinity;
    const tW = hw ? hw.t : Infinity;
    if (he && he.t < Math.min(tW, gT)) {
      const p = o.clone().addScaledVector(d, he.t);
      hit(p, d.clone().negate(), 'metal', true, he.head ? 'weak' : 'body');
      const killed = G.enemies.damage(he.e, 34 * (0.9 + Math.random() * 0.2), d, he.head);
      G.game.hitmark(killed);
      return { point: p };
    }
    if (tW < gT && tW < maxD) { const p = o.clone().addScaledVector(d, tW); hit(p, hw.n, hw.surface || 'metal'); return { point: p }; }
    if (gT < maxD) { const p = o.clone().addScaledVector(d, gT); const wet = G.puddleAt(p); hit(p, new THREE.Vector3(0, 1, 0), wet ? 'water' : 'concrete'); return { point: p }; }
    return null;
  }
  onEvent(name, data) {
    this.G.audio.emit(name, data);
    if (name === 'weapon:fire') { this.events.push('fire'); this.G.player.lastShot = this.G.t; }
    else if (name === 'weapon:dry') this.events.push('dry');
    else if (name === 'weapon:reload') this.events.push(data.phase === 'start' ? 'reload' : data.phase === 'done' ? 'reloaded' : data.phase);
  }
  muzzleFlash(pos, color, intensity, dist, ttl) {
    const L = this.G.lights.muzzle; L.position.copy(pos); L.color.set(color); L.distance = dist; L.intensity = intensity;
    this.flashPeak = intensity; this.flashTtl = this.flashDur = ttl;
  }
  get ammo() { return this.sl ? this.sl.ammo : RIFLE.mag; }
  get reserve() { return this.sl ? this.sl.reserve : RIFLE.reserve; }
  get ads() { return this.sl ? this.sl.ads : 0; }
  get busy() { return !!this.sl && this.sl.state === 'reloading'; }
  get bloom() { return this.sl ? Math.max(0, (this.sl.spread - 0.0125) / 0.0125) : 0; }
  get holder() { return this.root; }
  startReload() { this.reloadReq = true; return true; }
  startInspect() {}
  startMelee() { if (this.meleeT > 0) return false; this.meleeT = 0.55; return true; }
  // enemy rounds use Saltline's enemy tracer (warmer, wider); the player's come from the controller
  tracer(from, to, enemy) { if (this.G.slfx) this.G.slfx.tracer(from, to, enemy ? { color: 0xffc070, speed: 260, width: 0.035 } : {}); }
  update(dt, st) {
    const G = this.G;
    if (!this.sl) return;
    if (this.meleeT > 0) this.meleeT = Math.max(0, this.meleeT - dt);
    this.vmCam.aspect = G.camera.aspect; this.vmCam.updateProjectionMatrix();
    this.sl.update(dt);
    this.vmCam.position.copy(G.camera.position); this.vmCam.quaternion.copy(G.camera.quaternion); this.vmCam.updateMatrixWorld();
    // muzzle light: linear fade over its ttl
    if (this.flashTtl > 0) { this.flashTtl -= dt; G.lights.muzzle.intensity = Math.max(0, this.flashPeak * this.flashTtl / this.flashDur); } else G.lights.muzzle.intensity = 0;
    // wetness: rises in rain, dries indoors
    const target = st.indoor ? 0 : (U.uRain.value > 0 ? 1 : 0);
    this.wet = damp(this.wet, target, target > this.wet ? 0.25 : 0.06, dt);
    this.sl.setWetness(this.wet); U.uGunWet.value = this.wet;
  }
  draw(renderer) {
    renderer.autoClear = false;
    renderer.render(this.G.scene, this.vmCam);
  }
}
